// Package api is the product's JSON HTTP API.
package api

import (
	"encoding/json"
	"errors"
	"net/http"
	"time"

	"example.com/saasapi/internal/billing"
	"example.com/saasapi/internal/store"
)

// Options configure a Server.
type Options struct {
	// Now is the server's clock; nil means time.Now. Tests set it to move time without sleeping.
	Now func() time.Time
}

// Server serves the API.
type Server struct {
	store *store.Store
	now   func() time.Time
	mux   *http.ServeMux
}

// New returns a server over a store.
func New(st *store.Store, opt Options) *Server {
	s := &Server{store: st, now: opt.Now, mux: http.NewServeMux()}
	if s.now == nil {
		s.now = time.Now
	}
	s.mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	s.mux.HandleFunc("GET /api/customers", s.authed(s.listCustomers))
	s.mux.HandleFunc("POST /api/customers", s.authed(s.createCustomer))
	s.mux.HandleFunc("GET /api/customers/{id}", s.authed(s.getCustomer))
	s.mux.HandleFunc("GET /api/invoices", s.authed(s.listInvoices))
	s.mux.HandleFunc("POST /api/invoices", s.authed(s.createInvoice))
	s.mux.HandleFunc("GET /api/invoices/{id}", s.authed(s.getInvoice))
	return s
}

// ServeHTTP implements http.Handler.
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) { s.mux.ServeHTTP(w, r) }

// handler is an endpoint that runs for a known account.
type handler func(w http.ResponseWriter, r *http.Request, acct store.Account)

// authed resolves the X-API-Key header to its account, or answers 401.
func (s *Server) authed(h handler) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		acct, ok := s.store.AccountForKey(r.Header.Get("X-API-Key"))
		if !ok {
			writeError(w, http.StatusUnauthorized, "unauthorized")
			return
		}
		h(w, r, acct)
	}
}

func (s *Server) listCustomers(w http.ResponseWriter, r *http.Request, acct store.Account) {
	writeJSON(w, http.StatusOK, map[string]any{"items": s.store.Customers(acct.ID)})
}

func (s *Server) createCustomer(w http.ResponseWriter, r *http.Request, acct store.Account) {
	var in struct {
		Name  string     `json:"name"`
		Email string     `json:"email"`
		Plan  store.Plan `json:"plan"`
	}
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json")
		return
	}
	c, err := s.store.CreateCustomer(acct.ID, in.Name, in.Email, in.Plan, s.now())
	if err != nil {
		writeStoreError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, c)
}

func (s *Server) getCustomer(w http.ResponseWriter, r *http.Request, acct store.Account) {
	c, ok := s.store.Customer(acct.ID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found")
		return
	}
	writeJSON(w, http.StatusOK, c)
}

// invoiceView is an invoice with its totals.
type invoiceView struct {
	store.Invoice
	Totals billing.Totals `json:"totals"`
}

func view(inv store.Invoice) invoiceView {
	return invoiceView{Invoice: inv, Totals: billing.Compute(inv)}
}

func (s *Server) listInvoices(w http.ResponseWriter, r *http.Request, acct store.Account) {
	items := []invoiceView{}
	for _, inv := range s.store.Invoices(acct.ID) {
		items = append(items, view(inv))
	}
	writeJSON(w, http.StatusOK, map[string]any{"items": items})
}

func (s *Server) createInvoice(w http.ResponseWriter, r *http.Request, acct store.Account) {
	var in struct {
		CustomerID    string           `json:"customer_id"`
		Lines         []store.LineItem `json:"lines"`
		CouponPercent int              `json:"coupon_percent"`
		CreditCents   int64            `json:"credit_cents"`
	}
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json")
		return
	}
	inv, err := s.store.CreateInvoice(store.Invoice{AccountID: acct.ID, CustomerID: in.CustomerID, Lines: in.Lines, CouponPercent: in.CouponPercent, CreditCents: in.CreditCents}, s.now())
	if err != nil {
		writeStoreError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, view(inv))
}

func (s *Server) getInvoice(w http.ResponseWriter, r *http.Request, acct store.Account) {
	inv, ok := s.store.Invoice(acct.ID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found")
		return
	}
	writeJSON(w, http.StatusOK, view(inv))
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// writeError answers {"error": code}.
func writeError(w http.ResponseWriter, status int, code string) {
	writeJSON(w, status, map[string]string{"error": code})
}

func writeStoreError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		writeError(w, http.StatusNotFound, "not_found")
	case errors.Is(err, store.ErrInvalid):
		writeError(w, http.StatusUnprocessableEntity, "invalid")
	default:
		writeError(w, http.StatusInternalServerError, "internal")
	}
}
// Package store keeps the API's data in memory. It is safe for concurrent use.
package store

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"
)

// Plan is an account's or a customer's subscription plan.
type Plan string

const (
	PlanFree Plan = "free"
	PlanPro  Plan = "pro"
)

// Valid reports whether p is a known plan.
func (p Plan) Valid() bool { return p == PlanFree || p == PlanPro }

// Account is one tenant of the product.
type Account struct {
	ID   string
	Name string
	Plan Plan
	// TaxRateBP is the tax rate charged on this account's invoices, in basis points (1% = 100).
	TaxRateBP int
}

// Customer is one of an account's customers.
type Customer struct {
	ID        string    `json:"id"`
	AccountID string    `json:"-"`
	Name      string    `json:"name"`
	Email     string    `json:"email"`
	Plan      Plan      `json:"plan"`
	CreatedAt time.Time `json:"created_at"`
}

// LineItem is one line of an invoice.
type LineItem struct {
	Description string `json:"description"`
	Quantity    int    `json:"quantity"`
	UnitCents   int64  `json:"unit_cents"`
}

// Invoice is a bill to a customer.
type Invoice struct {
	ID         string     `json:"id"`
	AccountID  string     `json:"-"`
	CustomerID string     `json:"customer_id"`
	Lines      []LineItem `json:"lines"`
	// CouponPercent is a percentage discount (0 to 100).
	CouponPercent int `json:"coupon_percent"`
	// CreditCents is a fixed amount taken off the invoice.
	CreditCents int64     `json:"credit_cents"`
	TaxRateBP   int       `json:"tax_rate_bp"`
	CreatedAt   time.Time `json:"created_at"`
}

// Errors.
var (
	ErrNotFound = errors.New("not found")
	ErrInvalid  = errors.New("invalid")
)

// Store holds everything.
type Store struct {
	mu        sync.Mutex
	accounts  map[string]Account
	keys      map[string]string // API key -> account ID
	customers map[string]Customer
	invoices  map[string]Invoice
	seq       int
}

// New returns an empty store.
func New() *Store {
	return &Store{accounts: map[string]Account{}, keys: map[string]string{}, customers: map[string]Customer{}, invoices: map[string]Invoice{}}
}

// AddAccount adds or replaces an account.
func (s *Store) AddAccount(a Account) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.accounts[a.ID] = a
}

// AddKey gives an account an API key.
func (s *Store) AddKey(key, accountID string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.keys[key] = accountID
}

// AccountForKey returns the account an API key belongs to.
func (s *Store) AccountForKey(key string) (Account, bool) {
	if key == "" {
		return Account{}, false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	id, ok := s.keys[key]
	if !ok {
		return Account{}, false
	}
	a, ok := s.accounts[id]
	return a, ok
}

func (s *Store) next(prefix string) string {
	s.seq++
	return fmt.Sprintf("%s_%05d", prefix, s.seq)
}

// CreateCustomer adds a customer to an account.
func (s *Store) CreateCustomer(accountID, name, email string, plan Plan, now time.Time) (Customer, error) {
	name, email = strings.TrimSpace(name), strings.TrimSpace(email)
	if name == "" || !strings.Contains(email, "@") {
		return Customer{}, fmt.Errorf("%w: a customer needs a name and an email address", ErrInvalid)
	}
	if plan == "" {
		plan = PlanFree
	}
	if !plan.Valid() {
		return Customer{}, fmt.Errorf("%w: unknown plan %q", ErrInvalid, plan)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.accounts[accountID]; !ok {
		return Customer{}, ErrNotFound
	}
	c := Customer{ID: s.next("cus"), AccountID: accountID, Name: name, Email: email, Plan: plan, CreatedAt: now}
	s.customers[c.ID] = c
	return c, nil
}

// Customer returns one of an account's customers.
func (s *Store) Customer(accountID, id string) (Customer, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.AccountID != accountID {
		return Customer{}, false
	}
	return c, true
}

// Customers returns an account's customers sorted by ID.
func (s *Store) Customers(accountID string) []Customer {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Customer{}
	for _, c := range s.customers {
		if c.AccountID == accountID {
			out = append(out, c)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// CreateInvoice stores an invoice for one of the account's customers, with the account's tax rate.
func (s *Store) CreateInvoice(inv Invoice, now time.Time) (Invoice, error) {
	if len(inv.Lines) == 0 {
		return Invoice{}, fmt.Errorf("%w: an invoice needs at least one line", ErrInvalid)
	}
	for _, l := range inv.Lines {
		if l.Quantity <= 0 || l.UnitCents < 0 {
			return Invoice{}, fmt.Errorf("%w: a line needs a positive quantity and a price that is not negative", ErrInvalid)
		}
	}
	if inv.CouponPercent < 0 || inv.CouponPercent > 100 || inv.CreditCents < 0 {
		return Invoice{}, fmt.Errorf("%w: the coupon is 0 to 100 percent and the credit is not negative", ErrInvalid)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	a, ok := s.accounts[inv.AccountID]
	if !ok {
		return Invoice{}, ErrNotFound
	}
	if c, ok := s.customers[inv.CustomerID]; !ok || c.AccountID != inv.AccountID {
		return Invoice{}, ErrNotFound
	}
	inv.ID = s.next("inv")
	inv.TaxRateBP = a.TaxRateBP
	inv.CreatedAt = now
	inv.Lines = append([]LineItem(nil), inv.Lines...)
	s.invoices[inv.ID] = inv
	return inv, nil
}

// Invoice returns one of an account's invoices.
func (s *Store) Invoice(accountID, id string) (Invoice, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[id]
	if !ok || inv.AccountID != accountID {
		return Invoice{}, false
	}
	return inv, true
}

// Invoices returns an account's invoices, oldest first (ties by ID).
func (s *Store) Invoices(accountID string) []Invoice {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Invoice{}
	for _, inv := range s.invoices {
		if inv.AccountID == accountID {
			out = append(out, inv)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}
