func TestCustomersCSVIsTheCallersCustomersSortedByID(t *testing.T) {
	srv, st := newServer(t)
	// 05:06:07 at UTC+2 is 03:06:07 UTC.
	when := time.Date(2026, 3, 4, 5, 6, 7, 0, time.FixedZone("UTC+2", 2*3600))
	first, _ := st.CreateCustomer("acc_acme", "Jane Doe", "jane@example.com", store.PlanPro, when)
	st.CreateCustomer("acc_globex", "Hank", "hank@globex.test", store.PlanFree, when)
	second, _ := st.CreateCustomer("acc_acme", "Ann, Lee", "ann@example.com", store.PlanFree, when.Add(time.Hour))

	r := do(t, srv, "GET", "/api/customers.csv", "key-acme", "")
	if r.Code != http.StatusOK {
		t.Fatalf("export: %d %s", r.Code, r.Body)
	}
	if ct := r.Header().Get("Content-Type"); ct != "text/csv; charset=utf-8" {
		t.Fatalf("Content-Type %q", ct)
	}
	if cd := r.Header().Get("Content-Disposition"); cd != `attachment; filename="customers.csv"` {
		t.Fatalf("Content-Disposition %q", cd)
	}
	want := "id,name,email,plan,created_at\r\n" +
		first.ID + ",Jane Doe,jane@example.com,pro,2026-03-04T03:06:07Z\r\n" +
		second.ID + `,"Ann, Lee",ann@example.com,free,2026-03-04T04:06:07Z` + "\r\n"
	if got := r.Body.String(); got != want {
		t.Fatalf("body:\n%q\nwant:\n%q", got, want)
	}
}

func TestCustomersCSVWithNoCustomersIsJustTheHeader(t *testing.T) {
	srv, _ := newServer(t)
	r := do(t, srv, "GET", "/api/customers.csv", "key-acme", "")
	if r.Code != http.StatusOK || r.Body.String() != "id,name,email,plan,created_at\r\n" {
		t.Fatalf("status %d body %q", r.Code, r.Body)
	}
}

func TestCustomersCSVQuotesFieldsAndNeutralizesFormulas(t *testing.T) {
	srv, st := newServer(t)
	now := time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)
	names := []struct{ name, email string }{
		{`=HYPERLINK("http://x","click")`, "=x@evil.test"},
		{"+1 555", "+15@example.com"},
		{"@SUM(A1)", "-ann@example.com"},
		{"Quote \"Q\"\nNew line", "a=b@example.com"},
		{"Plain, not formula", "plain@example.com"},
	}
	var ids []string
	for _, n := range names {
		c, err := st.CreateCustomer("acc_acme", n.name, n.email, store.PlanFree, now)
		if err != nil {
			t.Fatal(err)
		}
		ids = append(ids, c.ID)
	}

	r := do(t, srv, "GET", "/api/customers.csv", "key-acme", "")
	if r.Code != http.StatusOK {
		t.Fatalf("export: %d", r.Code)
	}
	// encoding/csv rejects malformed quoting, so a parse that succeeds is valid RFC 4180.
	records, err := csv.NewReader(strings.NewReader(r.Body.String())).ReadAll()
	if err != nil {
		t.Fatalf("not valid CSV: %v\n%s", err, r.Body)
	}
	ts := "2026-01-02T03:04:05Z"
	want := [][]string{
		{"id", "name", "email", "plan", "created_at"},
		{ids[0], `'=HYPERLINK("http://x","click")`, "'=x@evil.test", "free", ts},
		{ids[1], "'+1 555", "'+15@example.com", "free", ts},
		{ids[2], "'@SUM(A1)", "'-ann@example.com", "free", ts},
		{ids[3], "Quote \"Q\"\nNew line", "a=b@example.com", "free", ts},
		{ids[4], "Plain, not formula", "plain@example.com", "free", ts},
	}
	if !reflect.DeepEqual(records, want) {
		t.Fatalf("records:\n%q\nwant:\n%q", records, want)
	}
}
